/**
 * Deteksi rekomendasi KBLI berdasarkan hasil pembelajaran data riil Sensus Ekonomi 2026 Mempawah
 */
export const getKbliSuggestionFromBusinessName = (rawName: string | null | undefined): KbliSuggestion | null => {
  if (!rawName) return null;
  
  // Bersihkan teks (abaikan nama orang di dalam tanda kurung)
  const clean = rawName
    .replace(/\(.*?\)|<.*?>|\[.*?\]/g, ' ')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  if (clean.length < 3) return null;

  // 1. Evaluasi frasa majemuk terlatih (Prioritas Utama: 2-gram dan 3-gram)
  for (let i = 0; i < SE2026_TRAINED_PHRASES.length; i++) {
    const [phrase, katKode, kbli5, cnt] = SE2026_TRAINED_PHRASES[i];
    if (clean.includes(phrase)) {
      const cat = KATEGORI_LAPANGAN_USAHA.find(k => k.kode === katKode);
      if (cat && cat.dianalisis) {
        return {
          kode: cat.kode,
          nama: cat.nama,
          singkat: cat.singkat,
          kbli5Digit: kbli5 || undefined,
          matchedKeyword: phrase,
          min: cat.min,
          max: cat.max,
          count: cnt
        };
      }
    }
  }

  // 2. Evaluasi kata tunggal terlatih (tokenisasi)
  const words = clean.split(' ').filter(w => w.length >= 3);
  for (let i = 0; i < SE2026_TRAINED_TOKENS.length; i++) {
    const [token, katKode, kbli5, cnt] = SE2026_TRAINED_TOKENS[i];
    if (words.includes(token) || (token.length >= 4 && clean.includes(token))) {
      const cat = KATEGORI_LAPANGAN_USAHA.find(k => k.kode === katKode);
      if (cat && cat.dianalisis) {
        return {
          kode: cat.kode,
          nama: cat.nama,
          singkat: cat.singkat,
          kbli5Digit: kbli5 || undefined,
          matchedKeyword: token,
          min: cat.min,
          max: cat.max,
          count: cnt
        };
      }
    }
  }

  return null;
};
